async handleCompareVersions(args) {
    if (!isValidCompareVersionsArgs(args)) {
        throw new McpError(ErrorCode.InvalidParams, 'Invalid arguments: dependency, version1, and version2 are required strings');
    }
    const coord = parseMavenCoordinate(args.dependency);
    const { version1, version2 } = args;
    try {
        const fetchVersionTimestamp = async (version) => {
            const query = `g:"${coord.groupId}" AND a:"${coord.artifactId}" AND v:"${version}"`;
            const response = await this.axiosInstance.get('', {
                params: {
                    q: query,
                    core: 'gav',
                    rows: 1,
                    wt: 'json',
                },
            });
            const docs = response.data.response.docs;
            if (!docs.length) {
                return null;
            }
            return docs[0].timestamp;
        };
        const [ts1, ts2] = await Promise.all([
            fetchVersionTimestamp(version1),
            fetchVersionTimestamp(version2),
        ]);
        if (ts1 === null && ts2 === null) {
            return {
                content: [{ type: 'text', text: `Neither version ${version1} nor ${version2} was found for ${coord.groupId}:${coord.artifactId}` }],
                isError: true,
            };
        }
        if (ts1 === null) {
            return {
                content: [{ type: 'text', text: `Version ${version1} was not found for ${coord.groupId}:${coord.artifactId}` }],
                isError: true,
            };
        }
        if (ts2 === null) {
            return {
                content: [{ type: 'text', text: `Version ${version2} was not found for ${coord.groupId}:${coord.artifactId}` }],
                isError: true,
            };
        }
        const date1 = new Date(ts1).toISOString().split('T')[0];
        const date2 = new Date(ts2).toISOString().split('T')[0];
        let result;
        if (ts1 > ts2) {
            result = `${version1} is newer than ${version2} (${date1} vs ${date2})`;
        } else if (ts2 > ts1) {
            result = `${version2} is newer than ${version1} (${date2} vs ${date1})`;
        } else {
            result = `${version1} and ${version2} were released at the same time (${date1})`;
        }
        return {
            content: [{ type: 'text', text: result }],
        };
    } catch (error) {
        if (axios.isAxiosError(error)) {
            return {
                content: [{ type: 'text', text: `Maven Central API error: ${error.response?.data?.error?.msg ?? error.message}` }],
                isError: true,
            };
        }
        throw error;
    }
}
