// Filter tool recommendations by confidence threshold and strategy
if (validatedInput.current_step?.recommended_tools) {
    let filteredTools = validatedInput.current_step.recommended_tools.filter(
        (tool) => tool.confidence >= confidenceThreshold
    );

    // Apply recommendation strategy
    if (recommendationStrategy === 'conservative') {
        filteredTools = filteredTools.filter((tool) => tool.confidence >= 0.7);
    } else if (recommendationStrategy === 'exploratory') {
        // Include alternatives in exploratory mode
        filteredTools.forEach((tool) => {
            if (tool.alternatives && tool.alternatives.length > 0) {
                console.error(`Exploratory mode: Consider alternatives for ${tool.tool_name}: ${tool.alternatives.join(', ')}`);
            }
        });
    }

    // Adjust recommendations based on tool execution feedback
    if (toolFeedback.length > 0) {
        const failedTools = new Set(
            toolFeedback.filter((fb) => !fb.success).map((fb) => fb.tool_name)
        );
        const successfulTools = toolFeedback.filter((fb) => fb.success).map((fb) => fb.tool_name);

        // Deprioritize failed tools
        filteredTools = filteredTools.map((tool) => {
            if (failedTools.has(tool.tool_name)) {
                console.error(`Tool ${tool.tool_name} previously failed, reducing priority`);
                return { ...tool, priority: tool.priority + 100, confidence: tool.confidence * 0.8 };
            }
            return tool;
        });

        // Log successful tool patterns
        if (successfulTools.length > 0) {
            console.error(`Previously successful tools: ${successfulTools.join(', ')}`);
        }
    }

    validatedInput.current_step.recommended_tools = filteredTools;
}

