const percentageCalculatorTool = {
    name: "percentage_calculator",
    definition: {
        title: "百分比计算器",
        description: "执行各种百分比计算，包括百分比变化、占比、加价、折扣等",
        inputSchema: {
            operation: z.enum(["percent_change", "percent_of_total", "markup", "discount", "find_percentage", "reverse_percentage"]).describe("操作类型：percent_change=百分比变化，percent_of_total=占总数百分比，markup=加价，discount=折扣，find_percentage=求百分比值，reverse_percentage=反向百分比"),
            value1: z.number().describe("第一个数值（原值、部分值或基数）"),
            value2: z.number().optional().describe("第二个数值（新值、总值或可选）"),
            percentage: z.number().min(0).max(100).optional().describe("百分比值（用于加价、折扣、求百分比等操作）")
        }
    },
    handler: async ({ operation, value1, value2, percentage }) => {
        switch (operation) {
            case "percent_change": {
                if (value2 === undefined) {
                    return createErrorResponse("百分比变化计算需要两个数值（原值和新值）！");
                }
                if (value1 === 0) {
                    return createErrorResponse("原值不能为零！");
                }
                const change = value2 - value1;
                const percentChange = (change / value1) * 100;
                const direction = change > 0 ? "增长" : change < 0 ? "下降" : "无变化";
                return createSuccessResponse(`百分比变化计算结果：\n` +
                    `原值：${value1.toFixed(2)}\n` +
                    `新值：${value2.toFixed(2)}\n` +
                    `变化量：${change.toFixed(2)}\n` +
                    `百分比变化：${percentChange.toFixed(2)}%\n` +
                    `变化方向：${direction}`);
            }
