    steps: z.array(BatchSchemaOpSchema).min(1).describe('Ordered list of schema operations to execute atomically'),
});

export const batchSchemaOpsTool = {
    name: 'pg_batch_schema_ops',
    description: 'Execute multiple schema operations (create_table, alter_table, drop_table, create_enum) atomically in a single transaction. If any step fails, all changes are rolled back. Use this instead of pg_manage_schema when you need multiple schema changes to succeed or fail together (e.g., complex migrations).',
    inputSchema: BatchSchemaOpsInputSchema,
    async execute(params, getConnectionString) {
        const validationResult = BatchSchemaOpsInputSchema.safeParse(params);
        if (!validationResult.success) {
            return { content: [{ type: 'text', text: `Invalid input: ${validationResult.error.format()}` }], isError: true };
        }
        const { connectionString: connStringArg, steps } = validationResult.data;
        const resolvedConnectionString = getConnectionString(connStringArg);
        const db = DatabaseConnection.getInstance();
        const results = [];
        try {
            await db.connect(resolvedConnectionString);
            await db.transaction(async (client) => {
                for (const step of steps) {
                    switch (step.operation) {
                        case 'create_table': {
                            if (!step.tableName || !step.columns || step.columns.length === 0) {
                                throw new Error('tableName and columns are required for create_table step');
                            }
                            const columnDefs = step.columns.map(col => {
                                let def = `"${col.name}" ${col.type}`;
                                if (col.nullable === false) def += ' NOT NULL';
                                if (col.default !== undefined) def += ` DEFAULT ${col.default}`;
                                return def;
                            }).join(', ');
                            await client.query(`CREATE TABLE IF NOT EXISTS "${step.tableName}" (${columnDefs})`);
                            results.push({ operation: 'create_table', tableName: step.tableName, status: 'ok' });
                            break;
                        }
                        case 'alter_table': {
                            if (!step.tableName || !step.operations || step.operations.length === 0) {
                                throw new Error('tableName and operations are required for alter_table step');
                            }
                            for (const op of step.operations) {
                                const colNameQuoted = `"${op.columnName}"`;
                                let sql = '';
                                switch (op.type) {
                                    case 'add':
                                        if (!op.dataType) throw new Error('Data type is required for ADD operation');
                                        sql = `ALTER TABLE "${step.tableName}" ADD COLUMN ${colNameQuoted} ${op.dataType}`;
                                        if (op.nullable === false) sql += ' NOT NULL';
                                        if (op.default !== undefined) sql += ` DEFAULT ${op.default}`;
                                        break;
                                    case 'alter': {
                                        const alterActions = [];
                                        if (op.dataType) alterActions.push(`TYPE ${op.dataType}`);
                                        if (op.nullable !== undefined) alterActions.push(op.nullable ? 'DROP NOT NULL' : 'SET NOT NULL');
                                        if (op.default !== undefined) alterActions.push(op.default === null || op.default === '' ? 'DROP DEFAULT' : `SET DEFAULT ${op.default}`);
                                        if (alterActions.length === 0) throw new Error('No alter action specified for column.');
                                        sql = `ALTER TABLE "${step.tableName}" ALTER COLUMN ${colNameQuoted} ${alterActions.join(' ')}`;
                                        break;
                                    }
                                    case 'drop':
                                        sql = `ALTER TABLE "${step.tableName}" DROP COLUMN ${colNameQuoted}`;
                                        break;
                                }
                                if (sql) await client.query(sql);
                            }
                            results.push({ operation: 'alter_table', tableName: step.tableName, status: 'ok' });
                            break;
                        }
                        case 'drop_table': {
                            if (!step.tableName) throw new Error('tableName is required for drop_table step');
                            const cascadeClause = step.cascade ? ' CASCADE' : '';
                            await client.query(`DROP TABLE IF EXISTS "${step.tableName}"${cascadeClause}`);
                            results.push({ operation: 'drop_table', tableName: step.tableName, status: 'ok' });
                            break;
                        }
                        case 'create_enum': {
                            if (!step.enumName || !step.values || step.values.length === 0) {
                                throw new Error('enumName and values are required for create_enum step');
                            }
                            const schemaName = step.schema || 'public';
                            const valuesPlaceholders = step.values.map((_, i) => `$${i + 1}`).join(', ');
                            const ifNotExistsClause = step.ifNotExists ? 'IF NOT EXISTS' : '';
                            await client.query(
                                `CREATE TYPE ${ifNotExistsClause} "${schemaName}"."${step.enumName}" AS ENUM (${valuesPlaceholders})`,
                                step.values
                            );
                            results.push({ operation: 'create_enum', enumName: step.enumName, schema: schemaName, status: 'ok' });
                            break;
                        }
                    }
                }
            });
            return {
                content: [
                    { type: 'text', text: `Batch schema operations completed successfully (${results.length} step(s)).` },
                    { type: 'text', text: JSON.stringify(results, null, 2) }
                ]
            };
        } catch (error) {
            const errorMessage = error instanceof McpError ? error.message : (error instanceof Error ? error.message : String(error));
            return { content: [{ type: 'text', text: `Batch schema operations failed (all changes rolled back): ${errorMessage}` }], isError: true };
