// Tool: duplicate_diagram
server.registerTool("duplicate_diagram", {
    description: "Duplicate the current diagram, optionally shifting all element positions by a given offset. " +
        "Sets the duplicated diagram as the active diagram and returns its XML. " +
        "Useful for creating variations of an existing diagram without starting from scratch.",
    inputSchema: {
        offset_x: z
            .number()
            .optional()
            .describe("Horizontal offset in pixels to shift all elements (default: 0)"),
        offset_y: z
            .number()
            .optional()
            .describe("Vertical offset in pixels to shift all elements (default: 0)"),
    },
}, async ({ offset_x = 0, offset_y = 0 }) => {
    try {
        if (!currentSession) {
            return {
                content: [
                    {
                        type: "text",
                        text: "Error: No active session. Please call start_session first.",
                    },
                ],
                isError: true,
            };
        }
        // Fetch latest state from browser
        const browserState = getState(currentSession.id);
        if (browserState?.xml) {
            currentSession.xml = browserState.xml;
        }
        if (!currentSession.xml) {
            return {
                content: [
                    {
                        type: "text",
                        text: "Error: No diagram to duplicate. Please create a diagram first with create_new_diagram.",
                    },
                ],
                isError: true,
            };
        }
        let duplicatedXml = currentSession.xml;
        // Apply position offset if requested
        if (offset_x !== 0 || offset_y !== 0) {
            duplicatedXml = duplicatedXml.replace(
                /(<mxGeometry\s[^>]*?)\bx="([^"]*)"/g,
                (match, prefix, xVal) => {
                    const newX = parseFloat(xVal) + offset_x;
                    return `${prefix}x="${newX}"`;
                }
            );
            duplicatedXml = duplicatedXml.replace(
                /(<mxGeometry\s[^>]*?)\by="([^"]*)"/g,
                (match, prefix, yVal) => {
                    const newY = parseFloat(yVal) + offset_y;
                    return `${prefix}y="${newY}"`;
                }
            );
        }
        // Validate the duplicated XML
        const { valid, error, fixed, fixes } = validateAndFixXml(duplicatedXml);
        if (fixed) {
            duplicatedXml = fixed;
            log.info(`Duplicate XML auto-fixed: ${fixes.join(", ")}`);
        }
        if (!valid && error) {
            log.error(`Duplicate XML validation failed: ${error}`);
            return {
                content: [
                    {
                        type: "text",
                        text: `Error: Duplicated XML validation failed - ${error}`,
                    },
                ],
                isError: true,
            };
        }
        // Save current state to history before replacing
        addHistory(currentSession.id, currentSession.xml, browserState?.svg || "");
        // Set duplicated diagram as active
        currentSession.xml = duplicatedXml;
        currentSession.version++;
        currentSession.lastGetDiagramTime = Date.now();
        setState(currentSession.id, duplicatedXml);
        addHistory(currentSession.id, duplicatedXml, "");
        log.info(`Diagram duplicated successfully (offset: ${offset_x}, ${offset_y})`);
        return {
            content: [
                {
                    type: "text",
                    text: `Diagram duplicated successfully!\n\nOffset applied: x=${offset_x}, y=${offset_y}\nXML length: ${duplicatedXml.length} characters\n\nThe duplicated diagram is now active in your browser.`,
