async batchGenerateDiagrams(args) {
    const { diagrams, return_markdown_embed = true } = args;
    if (!Array.isArray(diagrams) || diagrams.length === 0) {
        throw new Error('diagrams must be a non-empty array');
    }
    const results = [];
    for (const entry of diagrams) {
        const { id, plantuml_code, format = 'svg', output_path, diagram_name, validate_syntax = true } = entry;
        if (!plantuml_code) {
            results.push({ id: id ?? null, success: false, error: 'plantuml_code is required' });
            continue;
        }
        try {
            const encoded = encodePlantUML(plantuml_code);
            if (validate_syntax) {
                const validation = await this.validatePlantUMLSyntax(encoded, plantuml_code);
                if (!validation.isValid && validation.error) {
                    results.push({
                        id: id ?? null,
                        success: false,
                        validation_failed: true,
                        error_details: {
                            error_message: validation.error.message,
                            error_line: validation.error.line,
                            problematic_code: validation.error.problematic_code,
                            full_plantuml: validation.error.full_plantuml,
                            full_context: validation.error.full_context
                        }
                    });
                    continue;
                }
            }
            const diagramUrl = `${PLANTUML_SERVER_URL}/${format}/${encoded}`;
            const response = await fetch(diagramUrl);
            if (!response.ok) {
                results.push({ id: id ?? null, success: false, error: `PlantUML server returned ${response.status}: ${response.statusText}` });
                continue;
            }
            const sanitizedDiagramName = typeof diagram_name === 'string' && diagram_name.trim()
                ? diagram_name.trim().replace(/[\\/:*?"<>|]/g, '_')
                : 'diagram';
            const entryResult = {
                id: id ?? null,
                success: true,
                url: diagramUrl,
                format,
                ...(return_markdown_embed ? { markdown_embed: `![PlantUML Diagram](${diagramUrl})` } : {})
            };
            if (output_path) {
                let filePath = resolve(output_path);
                const fileExtension = extname(filePath).toLowerCase();
                const looksLikeDirectory = output_path.endsWith('/') || output_path.endsWith('\\');
                if (looksLikeDirectory) {
                    filePath = resolve(filePath, `${sanitizedDiagramName}.${format}`);
                } else if (!fileExtension) {
                    filePath = `${filePath}.${format}`;
                }
                const pathCheck = isPathAllowed(filePath);
                if (!pathCheck.allowed) {
                    results.push({ ...entryResult, success: false, error: `Security error: ${pathCheck.reason}` });
                    continue;
                }
                const dir = dirname(filePath);
                await mkdir(dir, { recursive: true });
                const arrayBuffer = await response.arrayBuffer();
                await writeFile(filePath, Buffer.from(arrayBuffer));
                results.push({ ...entryResult, local_path: filePath });
            } else {
                results.push(entryResult);
            }
        } catch (error) {
            results.push({ id: id ?? null, success: false, error: error instanceof Error ? error.message : String(error) });
        }
    }
    const successCount = results.filter(r => r.success).length;
    return {
        content: [
            {
                type: 'text',
                text: JSON.stringify({ total: diagrams.length, succeeded: successCount, failed: diagrams.length - successCount, results }, null, 2)
            }
        ]
    };
}
