export async function gcpComputeInstances(args) {
    try {
        const projectId = await getProjectId(args.project_id);
        let command = `compute instances list --project=${projectId} --format=json`;
        if (args.instance && args.zone) {
            command = `compute instances describe ${args.instance} --zone=${args.zone} --project=${projectId} --format=json`;
        }
        else if (args.instance) {
            command = `compute instances list --project=${projectId} --format=json --filter="name=${args.instance}"`;
        }
        else {
            if (args.zone) {
                command += ` --zones=${args.zone}`;
            }
            if (args.filter) {
                command += ` --filter="${args.filter}"`;
            }
        }
        const result = await executeGcloud(command, 30000);
        let instances = [];
        try {
            const parsed = JSON.parse(result.stdout || '[]');
            instances = Array.isArray(parsed) ? parsed : [parsed];
        }
        catch {
            instances = [];
        }
        const formattedOutput = instances.map((inst) => {
            const networkInterfaces = inst.networkInterfaces || [];
            const externalIp = networkInterfaces[0]?.accessConfigs?.[0]?.natIP || 'N/A';
            const internalIp = networkInterfaces[0]?.networkIP || 'N/A';
            return `Instance: ${inst.name || 'N/A'}\nStatus: ${inst.status || 'N/A'}\nZone: ${inst.zone?.split('/').pop() || 'N/A'}\nMachine Type: ${inst.machineType?.split('/').pop() || 'N/A'}\nInternal IP: ${internalIp}\nExternal IP: ${externalIp}\nCreated: ${inst.creationTimestamp || 'N/A'}\n---`;
        }).join('\n');
        return {
            content: [
                {
                    type: 'text',
                    text: formattedOutput || 'No instances found',
                },
            ],
        };
    }
    catch (error) {
        return {
            content: [
                {
                    type: 'text',
                    text: formatError(error),
                },
            ],
            isError: true,
        };
    }
}

