async getRelatedEntities(entityName, options = {}) {
    const graph = await this.loadGraph();
    const { direction = 'both', relationType } = options;
    // Find the source entity
    const sourceEntity = graph.entities.find(e => e.name === entityName);
    if (!sourceEntity) {
        throw new Error(`Entity with name ${entityName} not found`);
    }
    // Filter relations based on direction and type
    let relevantRelations = graph.relations.filter(r => {
        const matchesDirection = direction === 'both'
            ? (r.from === entityName || r.to === entityName)
            : direction === 'outgoing'
                ? r.from === entityName
                : r.to === entityName;
        const matchesType = relationType ? r.relationType === relationType : true;
        return matchesDirection && matchesType;
    });
    // Extract related entity names
    const relatedEntityNames = new Set();
    relevantRelations.forEach(r => {
        if (r.from === entityName) {
            relatedEntityNames.add(r.to);
        }
        if (r.to === entityName) {
            relatedEntityNames.add(r.from);
        }
    });
    // Get related entities
    const relatedEntities = graph.entities.filter(e => relatedEntityNames.has(e.name));
    return {
        sourceEntity,
        relatedEntities,
        relations: relevantRelations
    };
}

