        return almanac;
    }
    if (detailLevel === 'detailed' && !almanac[labels.分时]) {
        return almanac;
    }
    return almanac;
}

function applyLocaleToAlmanac(almanac, locale) {
    const labels = getLocalizedLabels(locale);
    if (locale === 'zh-CN') return almanac;

    const localized = {};
    Object.keys(almanac).forEach(key => {
        const newKey = labels[key] || key;
        if (typeof almanac[key] === 'object' && almanac[key] !== null && !Array.isArray(almanac[key])) {
            localized[newKey] = {};
            Object.keys(almanac[key]).forEach(subKey => {
                const newSubKey = labels[subKey] || subKey;
                localized[newKey][newSubKey] = almanac[key][subKey];
            });
        } else {
            localized[newKey] = almanac[key];
        }
    });
    return localized;
}

