    description: "Version, diff, and restore prompts generated by any prompt builder tool. Maintains an in-memory registry of named prompt versions with timestamps and metadata. Supports save, list, diff, restore, and delete operations. BEST FOR: prompt lifecycle management, iterative prompt refinement, A/B comparison of prompt variants, rollback to previous prompt versions. OUTPUTS: Version metadata, unified diffs between versions, or restored prompt content.",
    inputSchema: {
        type: "object",
        properties: {
            action: {
                type: "string",
                enum: ["save", "list", "diff", "restore", "delete"],
                description: "Operation to perform: 'save' stores a prompt version, 'list' shows all versions for a key, 'diff' computes line-level diff between two versions, 'restore' retrieves a specific version's content, 'delete' removes a version.",
            },
            key: {
                type: "string",
                description: "Logical name for the prompt (e.g., 'auth-system-prompt', 'onboarding-spec'). Groups versions under a shared identifier.",
                examples: ["auth-system-prompt", "payment-spec", "onboarding-flow"],
            },
            content: {
                type: "string",
                description: "Prompt content to save (required for 'save' action).",
            },
            label: {
                type: "string",
                description: "Optional human-readable label for the version (e.g., 'v1-initial', 'v2-with-cot').",
                examples: ["v1-initial", "v2-chain-of-thought", "v3-security-hardened"],
            },
            versionA: {
                type: "string",
                description: "Version ID or label for the base side of a diff (required for 'diff' action).",
            },
            versionB: {
                type: "string",
                description: "Version ID or label for the comparison side of a diff (required for 'diff' action). Omit to diff against the latest saved version.",
            },
            versionId: {
                type: "string",
                description: "Specific version ID to restore or delete (required for 'restore' and 'delete' actions).",
            },
            includeMetadata: {
                type: "boolean",
                description: "Include version metadata (timestamp, label, character count) in the response.",
                default: true,
            },
        },
        required: ["action", "key"],
    },
    annotations: {
        ...SESSION_TOOL_ANNOTATIONS,
        title: "Prompt Version Manager",
    },
},

case "prompt-version-manager": {
    const { action, key, content, label, versionA, versionB, versionId, includeMetadata = true } = args;
    // In-memory store scoped to the server process
    if (!global.__promptVersionStore) {
        global.__promptVersionStore = {};
    }
    const store = global.__promptVersionStore;
    if (!store[key]) store[key] = [];
    const versions = store[key];
    const now = new Date().toISOString();
    if (action === "save") {
        if (!content) throw new Error("'content' is required for save action.");
        const id = `${key}-v${versions.length + 1}-${Date.now()}`;
        const entry = { id, label: label ?? `v${versions.length + 1}`, content, savedAt: now, charCount: content.length };
        versions.push(entry);
        const meta = includeMetadata ? `\n\n**Metadata:** id=${entry.id}, label=${entry.label}, chars=${entry.charCount}, savedAt=${entry.savedAt}` : "";
        return { content: [{ type: "text", text: `Saved prompt version **${entry.label}** (id: \`${entry.id}\`) for key \`${key}\`.${meta}` }] };
    }
    if (action === "list") {
        if (versions.length === 0) return { content: [{ type: "text", text: `No versions found for key \`${key}\`.` }] };
        const rows = versions.map((v, i) => `${i + 1}. **${v.label}** — id: \`${v.id}\`, chars: ${v.charCount}, saved: ${v.savedAt}`).join("\n");
        return { content: [{ type: "text", text: `## Versions for \`${key}\`\n\n${rows}` }] };
    }
    if (action === "diff") {
        if (!versionA) throw new Error("'versionA' is required for diff action.");
        const findVer = (ref) => versions.find((v) => v.id === ref || v.label === ref);
        const va = findVer(versionA);
        if (!va) throw new Error(`Version '${versionA}' not found for key '${key}'.`);
        const vb = versionB ? findVer(versionB) : versions[versions.length - 1];
        if (!vb) throw new Error(`Version '${versionB}' not found for key '${key}'.`);
        const linesA = va.content.split("\n");
        const linesB = vb.content.split("\n");
        const diffLines = [];
        const maxLen = Math.max(linesA.length, linesB.length);
        for (let i = 0; i < maxLen; i++) {
            if (i >= linesA.length) diffLines.push(`+ ${linesB[i]}`);
            else if (i >= linesB.length) diffLines.push(`- ${linesA[i]}`);
            else if (linesA[i] !== linesB[i]) { diffLines.push(`- ${linesA[i]}`); diffLines.push(`+ ${linesB[i]}`); }
        }
        const diffText = diffLines.length === 0 ? "No differences found." : diffLines.join("\n");
        return { content: [{ type: "text", text: `## Diff: \`${va.label}\` → \`${vb.label}\` (key: \`${key}\`)\n\n\`\`\`diff\n${diffText}\n\`\`\`` }] };
    }
    if (action === "restore") {
        if (!versionId) throw new Error("'versionId' is required for restore action.");
        const ver = versions.find((v) => v.id === versionId || v.label === versionId);
        if (!ver) throw new Error(`Version '${versionId}' not found for key '${key}'.`);
        const meta = includeMetadata ? `\n\n**Metadata:** id=${ver.id}, label=${ver.label}, chars=${ver.charCount}, savedAt=${ver.savedAt}` : "";
        return { content: [{ type: "text", text: `## Restored: \`${ver.label}\` (key: \`${key}\`)${meta}\n\n${ver.content}` }] };
    }
    if (action === "delete") {
        if (!versionId) throw new Error("'versionId' is required for delete action.");
        const idx = versions.findIndex((v) => v.id === versionId || v.label === versionId);
        if (idx === -1) throw new Error(`Version '${versionId}' not found for key '${key}'.`);
        const removed = versions.splice(idx, 1)[0];
        return { content: [{ type: "text", text: `Deleted version **${removed.label}** (id: \`${removed.id}\`) from key \`${key}\`.` }] };
    }
    throw new Error(`Unknown action '${action}' for prompt-version-manager.`);
}
