async handleCheckOrderStatus(productName, spec) {
    const targetProduct = PRODUCTS.find(p => p.name === productName);
    if (!targetProduct) {
        throw new Error(`未找到商品：${productName}`);
    }
    if (!targetProduct.specs.includes(spec)) {
        throw new Error(`商品 ${productName} 不支持规格 ${spec}，支持的规格：${targetProduct.specs.join(" / ")}`);
    }
    const statusStages = ["已接单", "研磨咖啡豆", "萃取中", "调配中", "制作完成，请取餐"];
    const stageIndex = Math.floor(Math.random() * statusStages.length);
    const currentStatus = statusStages[stageIndex];
    const estimatedMinutes = stageIndex >= statusStages.length - 1 ? 0 : (statusStages.length - 1 - stageIndex) * 2;
    let responseText = `### 订单状态查询 ☕️\n\n`;
    responseText += `**商品**：${productName}\n`;
    responseText += `**规格**：${spec}\n`;
    responseText += `**当前状态**：${currentStatus}\n`;
    if (estimatedMinutes > 0) {
        responseText += `**预计等待**：约 ${estimatedMinutes} 分钟\n`;
