// rss.ts
function parseRSSFeed(xmlContent) {
  const isAtom = xmlContent.includes('<feed xmlns');
  const entries = [];

  if (isAtom) {
    const entryMatches = xmlContent.matchAll(/<entry[^>]*>([\s\S]*?)<\/entry>/g);
    for (const match of entryMatches) {
      const entryXml = match[1];
      const title = entryXml.match(/<title[^>]*>([\s\S]*?)<\/title>/)?.[1]?.replace(/<!\[CDATA\[|\]\]>/g, '').trim() || '';
      const link = entryXml.match(/<link[^>]*href=["']([^"']*)["']/)?.[1] || entryXml.match(/<link[^>]*>([^<]*)<\/link>/)?.[1] || '';
      const summary = entryXml.match(/<summary[^>]*>([\s\S]*?)<\/summary>/)?.[1]?.replace(/<!\[CDATA\[|\]\]>/g, '').replace(/<[^>]+>/g, '').trim() || '';
      const content = entryXml.match(/<content[^>]*>([\s\S]*?)<\/content>/)?.[1]?.replace(/<!\[CDATA\[|\]\]>/g, '').replace(/<[^>]+>/g, '').trim() || '';
      const published = entryXml.match(/<published[^>]*>([^<]*)<\/published>/)?.[1] || entryXml.match(/<updated[^>]*>([^<]*)<\/updated>/)?.[1] || '';

      entries.push({
        title,
        link,
        description: content || summary,
        pubDate: published
      });
    }
  } else {
    const itemMatches = xmlContent.matchAll(/<item[^>]*>([\s\S]*?)<\/item>/g);
    for (const match of itemMatches) {
      const itemXml = match[1];
      const title = itemXml.match(/<title[^>]*>([\s\S]*?)<\/title>/)?.[1]?.replace(/<!\[CDATA\[|\]\]>/g, '').trim() || '';
      const link = itemXml.match(/<link[^>]*>([^<]*)<\/link>/)?.[1]?.trim() || '';
      const description = itemXml.match(/<description[^>]*>([\s\S]*?)<\/description>/)?.[1]?.replace(/<!\[CDATA\[|\]\]>/g, '').replace(/<[^>]+>/g, '').trim() || '';
      const pubDate = itemXml.match(/<pubDate[^>]*>([^<]*)<\/pubDate>/)?.[1] || '';

      entries.push({
        title,
        link,
        description,
        pubDate
      });
    }
  }

  const feedTitle = xmlContent.match(/<title[^>]*>([\s\S]*?)<\/title>/)?.[1]?.replace(/<!\[CDATA\[|\]\]>/g, '').trim() || 'Unknown Feed';

  return {
    feedTitle,
    entries
  };
}

