var getComponentFullTool = {
  name: "get_component_full",
  description: `Get complete component information in a single call: documentation, source code, and CSS styles.
Accepts an array of component names and fetches all three data types in parallel for maximum efficiency.
Use this when you need two or more of: documentation, source code, styles - avoids multiple sequential calls.
Returns a unified response with sections for docs, source, and styles per component.
Control what is fetched with includeSource (default: true) and includeStyles (default: true).
Documentation includes: import statements, usage examples, props, variants, API reference.
Source code shows internal React/TypeScript implementation built on React Aria Components.
Styles show BEM CSS classes from @heroui/styles package.
IMPORTANT: Do NOT copy source code directly - use components via @heroui/react imports.
IMPORTANT: Do NOT mix BEM classes with React components - they are separate approaches.
Workflow: list_components \u2192 get_component_full.`,
  async ctx(shared) {
    return {
      componentList: shared?.componentList || []
    };
  },
  exec(server, { config, name, description, ctx }) {
    const inputSchema2 = z.object({
      components: z.array(z.enum(ctx.componentList)).min(1).describe(`Array of component names from list_components (case-sensitive).\nExamples: ["Button"], ["Card", "TextField"].\nDO NOT guess names - always verify with list_components first.`),
      includeSource: z.boolean().optional().describe("Include component source code in response (default: true)"),
      includeStyles: z.boolean().optional().describe("Include component CSS styles in response (default: true)"),
      format: z.enum(["markdown", "json"]).optional().describe("Output format: 'markdown' (default) or 'json'")
    });
    const handler = async ({ components, includeSource = true, includeStyles = true, format = "markdown" }) => {
      try {
        const fetchPromises = [
          fetchApi("/v1/components/docs", config.apiBaseUrl, {
            method: "POST",
            body: JSON.stringify({ components })
          })
        ];
        const sourceIndex = includeSource ? fetchPromises.push(
          fetchApi("/v1/components/source", config.apiBaseUrl, {
            method: "POST",
            body: JSON.stringify({ components })
          }).catch((err) => { console.error("Failed to fetch source code:", err); return null; })
        ) - 1 : -1;
        const stylesIndex = includeStyles ? fetchPromises.push(
          fetchApi("/v1/components/styles", config.apiBaseUrl, {
            method: "POST",
            body: JSON.stringify({ components })
          }).catch((err) => { console.error("Failed to fetch styles:", err); return null; })
        ) - 1 : -1;
        const results = await Promise.all(fetchPromises);
        const docsResponse = results[0];
        const sourceResponse = sourceIndex >= 0 ? results[sourceIndex] : null;
        const stylesResponse = stylesIndex >= 0 ? results[stylesIndex] : null;
        if (format === "json") {
          const jsonResults = docsResponse.results.map((docResult, index) => {
            const result = {
              component: docResult.component,
              documentation: {
                url: docResult.url,
                content: docResult.content,
                error: docResult.error
              }
            };
            if (includeSource && sourceResponse?.results?.[index]) {
              result.sourceCode = {
                filePath: sourceResponse.results[index].filePath,
                githubUrl: sourceResponse.results[index].githubUrl,
                code: sourceResponse.results[index].sourceCode,
                error: sourceResponse.results[index].error
              };
            }
            if (includeStyles && stylesResponse?.results?.[index]) {
              result.styles = {
                filePath: stylesResponse.results[index].filePath,
                githubUrl: stylesResponse.results[index].githubUrl,
                code: stylesResponse.results[index].stylesCode,
                error: stylesResponse.results[index].error
              };
            }
            return result;
          });
          return {
            content: [
              {
                type: "text",
                text: JSON.stringify({ results: jsonResults, _warning: docsResponse._warning }, null, 2)
              }
            ]
          };
        }
        let responseText = "";
        if (docsResponse._warning) {
          responseText += `${docsResponse._warning}\n\n`;
        }
        docsResponse.results.forEach((result, index) => {
          if (index > 0) responseText += "\n\n---\n\n";
          if (result.error || !result.content) {
            responseText += `# ${result.component}\n\n`;
            responseText += `## Documentation\n\nError: ${result.error}\n`;
            if (result.status) responseText += `Status: ${result.status}\n`;
          } else {
            responseText += `# ${result.component}\n\n`;
            responseText += `## Documentation\n\n`;
            responseText += `**URL:** ${result.url}\n\n---\n\n`;
            responseText += result.content;
          }
          if (includeSource && sourceResponse?.results?.[index]) {
            const sourceResult = sourceResponse.results[index];
            responseText += "\n\n";
            if (sourceResult.error || !sourceResult.sourceCode) {
              responseText += `## Source Code\n\nError: ${sourceResult.error || "Source code not available"}\n`;
            } else {
              responseText += `## Source Code\n\n`;
              responseText += `**File:** \`${sourceResult.filePath}\`\n`;
              responseText += `**GitHub:** [View on GitHub](${sourceResult.githubUrl})\n\n`;
              responseText += `\`\`\`tsx\n${sourceResult.sourceCode}\n\`\`\`\n`;
            }
          }
          if (includeStyles && stylesResponse?.results?.[index]) {
            const stylesResult = stylesResponse.results[index];
            responseText += "\n\n";
            if (stylesResult.error || !stylesResult.stylesCode) {
              responseText += `## Styles\n\nError: ${stylesResult.error || "Styles not available"}\n`;
            } else {
              responseText += `## Styles\n\n`;
              responseText += `**File:** \`${stylesResult.filePath}\`\n`;
              responseText += `**GitHub:** [View on GitHub](${stylesResult.githubUrl})\n\n`;
              responseText += `\`\`\`css\n${stylesResult.stylesCode}\n\`\`\`\n`;
            }
          }
        });
        return {
          content: [
            {
              type: "text",
              text: responseText
            }
          ]
        };
      } catch (error) {
        return {
          content: [
            {
              type: "text",
              text: `Error: Unable to get full component information. ${error instanceof Error ? error.message : "Unknown error"}`
            }
          ]
        };
      }
    };
    server.registerTool(name, { description, inputSchema: inputSchema2.shape }, handler);
  }
};
