server.tool(
    "read_multiple_files",
    "Read the contents of multiple files simultaneously. This is more efficient than reading files one by one when you need to analyze or compare multiple files.",
    {
        paths: z.array(z.string()).describe("Array of file paths to read"),
        encoding: z.string().optional().default('utf-8').describe("File encoding (default: utf-8)"),
        includeMetadata: z.boolean().optional().default(false).describe("Prepend file metadata (size, last modified) before each file's content"),
        ignoreErrors: z.boolean().optional().default(false).describe("Silently skip files that cannot be read instead of including error messages"),
        separator: z.string().optional().default('---').describe("Separator string inserted between file contents (default: '---')")
    },
    async ({ paths, encoding, includeMetadata, ignoreErrors, separator }) => {
        try {
            const results = await Promise.all(
                paths.map(async (filePath) => {
                    try {
                        const resolvedPath = await resolvePath(filePath);
                        const content = await fs.readFile(resolvedPath, encoding);
                        if (includeMetadata) {
                            const stats = await fs.stat(resolvedPath);
                            const meta = `[size: ${stats.size} bytes, modified: ${stats.mtime.toLocaleString()}]`;
                            return `${filePath} ${meta}:\n${content}\n`;
                        }
                        return `${filePath}:\n${content}\n`;
                    } catch (error) {
                        if (ignoreErrors) {
                            return null;
                        }
                        return `${filePath}: Error - ${error.message}`;
                    }
                })
            );
            const filtered = results.filter(r => r !== null);
            return {
                content: [{ type: "text", text: filtered.join(`\n${separator}\n`) }]
            };
        } catch (error) {
            return {
                content: [{ type: "text", text: `Error: ${error.message}` }],
                isError: true
            };
        }
    }
);

