    // Build QR options
    const qrOptions = {
      width: params.arguments.size || 200,
      margin: typeof params.arguments.margin === 'number' ? params.arguments.margin : 2,
      errorCorrectionLevel: errorCorrectionLevel,
      color: {
        dark: params.arguments.darkColor || '#000000',
