diff_hunks.new_code:
async runWorkflow(workflowName, focus, projectPath, prompt, excludePaths, severity_threshold, output_format) {
    const userLanguage = 'en';
    // STEP 1: Ambiguity detection - return clarification if BOTH missing
    if (!workflowName && !focus) {
        return buildClarificationResponse(userLanguage);
    }
    // STEP 2: Validate focus if provided
    if (focus && !isValidFocus(focus)) {
        return buildInvalidFocusResponse(focus, userLanguage);
    }
    // STEP 3: Select workflow (explicit workflow OR smart selection)
    const selectedWorkflow = workflowName || selectWorkflowByFocus(focus);
    // STEP 4: Build context, injecting optional params as metadata hints
    const contextFiles = prompt ? [prompt] : [];
    if (excludePaths && excludePaths.length > 0) {
        contextFiles.push(`excludePaths:${excludePaths.join(',')}`);
    }
    if (severity_threshold) {
        contextFiles.push(`severity_threshold:${severity_threshold}`);
    }
    // STEP 5: Execute pipeline
    const pipeline = createWorkflow(selectedWorkflow, contextFiles, projectPath || '.');
    const result = await pipeline.execute();
    // STEP 6: Apply output_format filtering
    const resolvedFormat = output_format || 'full';
    if (resolvedFormat === 'minimal') {
        return {
            content: [
                {
                    type: 'text',
                    text: JSON.stringify({
                        success: result.success,
                        workflow: selectedWorkflow,
                        errors: result.errors,
                    }, null, 2),
                },
            ],
        };
    }
    if (resolvedFormat === 'summary') {
        return {
            content: [
                {
                    type: 'text',
                    text: JSON.stringify({
                        success: result.success,
                        workflow: selectedWorkflow,
                        focus: focus || null,
                        totalDuration: result.totalDuration,
                        stepCount: result.steps ? result.steps.length : 0,
                        errorCount: result.errors ? result.errors.length : 0,
                        errors: result.errors,
                    }, null, 2),
                },
            ],
        };
    }
    // Default: 'full' — use existing response builder
    return buildSuccessResponse(selectedWorkflow, focus, result);
}

