function refineTicketsInfo(ticketsInfo, fromStation, toStation, includeNoTicketTrains = true, seatTypes = '', directOnly = false, trainCodes = '', arriveBeforeHour = 24, requireAvailableSeatTypes = '') {
    const seatTypeSet = new Set(seatTypes
        .split('|')
        .map((seatType) => seatType.trim())
        .filter((seatType) => seatType.length > 0));
    const trainCodeSet = new Set(trainCodes
        .split('|')
        .map((trainCode) => trainCode.trim().toUpperCase())
        .filter((trainCode) => trainCode.length > 0));
    const requiredSeatTypeSet = new Set(requireAvailableSeatTypes
        .split('|')
        .map((seatType) => seatType.trim().toLowerCase())
        .filter((seatType) => seatType.length > 0));
    let result = ticketsInfo.map((ticketInfo) => {
        const prices = seatTypeSet.size === 0
            ? ticketInfo.prices
            : ticketInfo.prices.filter((price) => seatTypeSet.has(price.short));
        return {
            ...ticketInfo,
            prices,
        };
    });
    if (directOnly) {
        result = result.filter((ticketInfo) => ticketInfo.from_station_telecode === fromStation &&
            ticketInfo.to_station_telecode === toStation);
    }
    if (trainCodeSet.size > 0) {
        result = result.filter((ticketInfo) => trainCodeSet.has(ticketInfo.start_train_code.toUpperCase()));
    }
    if (arriveBeforeHour < 24) {
        result = result.filter((ticketInfo) => {
            const arriveTimeHour = parseInt(ticketInfo.arrive_time.split(':')[0], 10);
            return arriveTimeHour <= arriveBeforeHour;
        });
    }
    if (requiredSeatTypeSet.size > 0) {
        result = result.filter((ticketInfo) => ticketInfo.prices.some((price) => requiredSeatTypeSet.has(price.short) && isSeatAvailable(price.num)));
    }
    if (!includeNoTicketTrains) {
        result = result.filter((ticketInfo) => ticketInfo.prices.some((price) => isSeatAvailable(price.num)));
    }
    return result;
}

